// Writes the generated files the site needs. Runs automatically before `npm start` and as the hosting build step.
//   server/registry.js        one static require() per game (bundlers and serverless hosts cannot list folders)
//   server/models.json        the .glb files in public/models/
//   public/models-list.json   the same list for static hosts (served at /models/list by a rewrite)
//   public/vendor/*.min.js    the Socket.IO and PeerJS browser libraries, copied from node_modules
//   public/host-worker.js     the room hub bundled to run in a browser (peer-to-peer hosting, see server/host-worker.js)
//   public/config.js          which transport this deployment uses
// Run it by hand after adding a game or a model if you start the server some other way:  node server/build-manifest.js
const fs = require('fs'), path = require('path');
const root = path.join(__dirname, '..'), pub = path.join(root, 'public');
const games = fs.readdirSync(path.join(__dirname, 'games')).filter((f) => f.endsWith('.js')).sort();
fs.writeFileSync(path.join(__dirname, 'registry.js'), '// GENERATED by server/build-manifest.js. Do not edit.\nmodule.exports = [\n' + games.map((f) => `  require('./games/${f}'),`).join('\n') + '\n];\n');
let models = []; try { models = fs.readdirSync(path.join(pub, 'models')).filter((f) => /\.(glb|gltf)$/i.test(f)).sort(); } catch (e) { /* none yet */ }
fs.writeFileSync(path.join(__dirname, 'models.json'), JSON.stringify(models) + '\n');
fs.writeFileSync(path.join(pub, 'models-list.json'), JSON.stringify(models) + '\n');
fs.mkdirSync(path.join(pub, 'vendor'), { recursive: true });
for (const [from, to] of [['socket.io/client-dist/socket.io.min.js', 'socket.io.min.js'], ['peerjs/dist/peerjs.min.js', 'peerjs.min.js']]) {
  try { fs.copyFileSync(path.join(root, 'node_modules', from), path.join(pub, 'vendor', to)); } catch (e) { if (!fs.existsSync(path.join(pub, 'vendor', to))) console.warn('missing ' + from); }
}
// A static host has no game server, so players connect to each other instead. Vercel sets VERCEL=1 while building.
const serverUrl = /^(https:\/\/[\w.-]+|http:\/\/localhost)(:\d+)?\/?$/.test(process.env.FG_SERVER_URL || '') ? process.env.FG_SERVER_URL.replace(/\/$/, '') : ''; /* a game server elsewhere (e.g. Render): the static site connects to it instead of peer-to-peer */
const p2p = !serverUrl && (!!process.env.VERCEL || process.env.FG_P2P === '1');
let ice = []; try { ice = JSON.parse(process.env.FG_ICE_SERVERS || '[]'); if (!Array.isArray(ice)) ice = []; } catch (e) { console.warn('FG_ICE_SERVERS is not a JSON array; ignored'); } /* relay (TURN) servers for players whose networks block direct links */
fs.writeFileSync(path.join(pub, 'config.js'), `// GENERATED by server/build-manifest.js. true = no game server here, players connect peer-to-peer (public/p2p.js).\nwindow.FG_P2P = ${p2p};\n// Extra ICE (TURN relay) servers from the FG_ICE_SERVERS build variable.\nwindow.FG_ICE = ${JSON.stringify(ice)};\n// Game server to connect to from a static site (FG_SERVER_URL); empty = this site's own server or peer-to-peer.\nwindow.FG_SERVER = ${JSON.stringify(serverUrl)};\n`);
let worker = 'skipped';
try {
  require('esbuild').buildSync({ entryPoints: [path.join(__dirname, 'host-worker.js')], outfile: path.join(pub, 'host-worker.js'), bundle: true, platform: 'browser', format: 'iife', target: 'es2020', minify: true, legalComments: 'none', logLevel: 'silent', define: { global: 'self' } });
  worker = Math.round(fs.statSync(path.join(pub, 'host-worker.js')).size / 1024) + ' KB';
} catch (e) { if (!fs.existsSync(path.join(pub, 'host-worker.js'))) console.warn('could not build public/host-worker.js: ' + e.message.split('\n')[0]); else worker = 'kept the existing file'; }
console.log(`manifest: ${games.length} games, ${models.length} models, host worker ${worker}, transport ${p2p ? 'peer-to-peer' : serverUrl ? 'server at ' + serverUrl : 'server'}`);
